{
  "checks": [
    {
      "problem": "链路明细里每个产品只展示开头几步的截图，后面的步骤没有图，读者无法在页面上核对问题清单和结论提到的那些界面。",
      "A": "没解决",
      "B": "解决"
    },
    {
      "problem": "问题清单、改进建议和链路明细之间没有互相引用的定位信息（问题编号、步骤号、屏名），读者要在几节之间来回数步骤、对编号才能把问题、建议和对应界面一一对上。",
      "A": "部分解决",
      "B": "解决"
    }
  ],
  "worse": [
    {
      "version": "A",
      "where": "链路明细",
      "why": "协作宝只到第 4 步、链工只到第 4 步，各缺一半截图，而小标题仍写「共 13 张」，读者按这句话去找第 5～8 步的界面会找不到；问题表里的 P3（第 6 步）、P4（第 5 步）和结论提到的「预订成功」屏在页面上根本没有对应图可核对。"
    }
  ],
  "better": "B",
  "reason": "B 把两款产品全部 13 张截图逐屏列出，并在每步标题上直接标注对应的问题编号（如「第 2 步·会议室列表·P2」「第 6 步·添加参会人·P3」），读者核对问题、建议与界面时不用再翻找缺失的图或来回数步骤；A 只放前 4 步，问题表里的第 5、6 步问题和结论提到的成功页都无图可对。",
  "next": [
    {
      "where": "链路明细（各步标题上的 P1～P4）",
      "task": "看到某一步标着 P2，想知道这一步到底是什么问题、多严重",
      "why": "标题只给编号，没有一句话问题描述和严重度，读者必须滚回页面下方的「问题」表逐行对照，再滚回来。"
    },
    {
      "where": "分环节",
      "task": "想核对某一环节（如「找空闲」「容量检查」）在两款产品里的实际界面",
      "why": "环节行只有文字描述，没有步骤号或问题编号，读者只能在链路明细的两块截图里逐张找对应屏。"
    },
    {
      "where": "结论",
      "task": "想验证结论里「找空闲时段要反复左右滑动时间轴」「先选楼层和会议室再找时间」这些说法",
      "why": "结论不带定位（第几步、哪张图），读者要自己判断该看哪几条链路和哪几个问题。"
    },
    {
      "where": "链路明细（两款产品上下分成两块）",
      "task": "想对照同一阶段（如「确认预订」「预订成功」）两款产品的界面差异",
      "why": "同一阶段的两张图分别落在协作宝块和链工块里，中间隔了好几行截图，要来回滚动才能并排比较。"
    }
  ]
}
